import xiaozhi.modules.conversation.ConversationModels.*;
import xiaozhi.modules.externalidentity.*;
import xiaozhi.modules.externalidentity.ExternalModels.*;

/** Real immutable dispatch/identity/transaction ledgers in a NEW retained schema; SDK usage values below are explicit controlled fixtures. */
@EnabledIfEnvironmentVariable(named="AI_PROVIDER_AUDIT_TEST_JDBC_URL",matches=".+")
class AiProviderUsageAuditPersistenceTest {
    static JdbcTemplate db;static DataSourceTransactionManager manager;static ObjectMapper json;static AtomicLong users=new AtomicLong(2200);
    AiExecutionService ai;AiProviderUsageAudit audit;ConversationService conversations;ExternalIdentityService identity;ExternalSettings settings;byte[] signing;
    long owner;String conversation,bearer;Principal principal;
    static <T>ObjectProvider<T> provider(Class<T> type,T value){var factory=new DefaultListableBeanFactory();factory.registerSingleton("fixture",value);return factory.getBeanProvider(type);}
    @BeforeAll static void database()throws Exception {
        String url=System.getenv("AI_PROVIDER_AUDIT_TEST_JDBC_URL");if(!url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/xiaozhi_ai_provider_audit_test_[a-z0-9_]+(\\?.*)?"))throw new IllegalArgumentException("Only a NEW xiaozhi_ai_provider_audit_test_* loopback schema is allowed");
        var source=new DriverManagerDataSource(url,"root",System.getenv("AI_PROVIDER_AUDIT_TEST_DB_PASSWORD"));db=new JdbcTemplate(source);manager=new DataSourceTransactionManager(source);json=new xiaozhi.modules.security.config.WebMvcConfig().jackson2HttpMessageConverter().getObjectMapper();assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Long.class),"Never reset any existing schema");
        db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY,status TINYINT NOT NULL,super_admin TINYINT NOT NULL DEFAULT 0,username VARCHAR(80) UNIQUE,password VARCHAR(100),create_date DATETIME(3))");db.execute("CREATE TABLE ai_agent(id VARCHAR(32) PRIMARY KEY,user_id BIGINT)");
        for(String name:List.of("conversation","support","ai-execution","ai-provider-request-usage","ai-provider-attempt-audit","external-identity","agent-tools"))try(var connection=source.getConnection();var migration=new Liquibase("db/changelog/"+name+".changelog.yaml",new ClassLoaderResourceAccessor(),new JdbcConnection(connection))){migration.update(new Contexts());migration.update(new Contexts());}assertEquals(9,db.queryForObject("SELECT COUNT(*) FROM DATABASECHANGELOG",Long.class));
    }
    @BeforeEach void fixture(){owner=users.incrementAndGet();db.update("INSERT INTO sys_user(id,status,super_admin,username) VALUES(?,1,0,?)",owner,"provider-audit-local-"+owner);audit=new AiProviderUsageAudit(db,manager);ai=new AiExecutionService(db,json,manager);ai.setEnabled(true);ai.setModel("qwen-flash");ai.setUsageAudit(audit);conversations=new ConversationService(new ConversationDao(db),json,manager);conversations.setAiExecution(ai);
        signing=new byte[32];new java.security.SecureRandom().nextBytes(signing);settings=new ExternalSettings();settings.setEnabled(true);settings.setKeysJson("{\"xiaozhi-audit-key\":{\"issuer\":\"xiaozhi-provider-audit-test\",\"secret_b64\":\""+Base64.getEncoder().encodeToString(signing)+"\"}}");identity=new ExternalIdentityService(db,json,manager,settings);
    }
    @AfterEach void retainFixtures(){RequestContextHolder.resetRequestAttributes();ai.setEnabled(true);db.update("UPDATE sys_user SET status=1 WHERE id=?",owner);if(conversation!=null)for(String run:db.query("SELECT id FROM ai_run WHERE conversation_id=? AND active_slot=1",(r,n)->r.getString(1),conversation))ai.cancel(owner,conversation,run);}
    void connect(boolean external)throws Exception {
        if(external){bearer=login();principal=identity.authenticate(bearer);owner=principal.userId();var request=new MockHttpServletRequest();request.setAttribute(ExternalIdentityService.ATTRIBUTE,principal);RequestContextHolder.setRequestAttributes(new ServletRequestAttributes(request));var tools=new AgentToolService(db,json,manager);tools.setEnabled(true);tools.setTechnicalEnabled(true);tools.setIdentity(identity);var core=new AgentToolExecutionCore(db,json);core.setEnabled(true);core.setTechnicalEnabled(true);core.setIdentity(identity);ReflectionTestUtils.setField(tools,"executionCore",core);ai.setAgentTools(provider(AgentToolService.class,tools));}
        conversation=conversations.create(owner,new CreateConversation("Provider fee audit fixture",null)).id();conversations.send(owner,conversation,new SendMessage(uuid(),List.of(new MessagePart("text","Controlled usage fixture; no real cloud provider",null,null,null,null,null,null))));
    }
    String login()throws Exception {var node=json.createObjectNode().put("external_subject","provider-audit-"+users.get()).put("source_session_id","audit-source-session").put("source_expires_at",Long.toString(Instant.now().getEpochSecond()+3600)).put("display_name","Audit fixture");node.putObject("tenant").put("type","company").put("id","1");var scope=node.putObject("scope");scope.putArray("project_ids");scope.putArray("device_ids");byte[] raw=json.writeValueAsBytes(node);String timestamp=Long.toString(Instant.now().getEpochSecond()),nonce=uuid();var headers=Map.of("x-external-key-id",List.of("xiaozhi-audit-key"),"x-external-timestamp",List.of(timestamp),"x-external-nonce",List.of(nonce),"x-external-signature",List.of(ExternalIdentityService.signature(signing,ExternalIdentityService.ISSUE,timestamp,nonce,raw)));var ticket=identity.issue(identity.verify(ExternalIdentityService.ISSUE,raw,headers),raw);return identity.exchange(ticket.ticket()).token();}
    Task claim(){Task task=ai.claim(new Claim("audit-fixture-worker"));assertNotNull(task);assertEquals(conversation,task.conversationId());return task;}
    ProviderRequest known(int round){return new ProviderRequest(round,null,new Usage(5L,2L,7L),round==1?"tool_calls":"stop");}
    UsageAudit report(Task task,ProviderRequest... requests){return new UsageAudit(task.leaseToken(),task.attempt(),List.of(requests));}
    long count(String sql,Object...args){return db.queryForObject(sql,Long.class,args);}static String uuid(){return UUID.randomUUID().toString().replace("-","");}
    @Test void claimCapturesImmutableDispatchAndTaskCapabilityWithoutExposingHash()throws Exception {connect(false);Task task=claim();assertTrue(task.usageAudit());var row=db.queryForMap("SELECT * FROM ai_provider_attempt_dispatch WHERE run_id=?",task.runId());assertNotEquals(task.leaseToken(),row.get("lease_hash"));assertEquals(64,((String)row.get("lease_hash")).length());assertEquals(task.controlEpoch(),((Number)row.get("control_epoch")).longValue());assertEquals(task.model(),row.get("model"));assertFalse(json.valueToTree(task).has("lease_hash"));assertEquals(1,count("SELECT COUNT(*) FROM ai_provider_attempt_dispatch WHERE run_id=?",task.runId()));}
    @Test void cancellationCanClearLeaseButLateAuditPreservesOnlyActualFees()throws Exception {connect(false);Task task=claim();ai.cancel(owner,conversation,task.runId());long events=count("SELECT last_event_seq FROM ai_conversation WHERE id=?",conversation);assertNull(db.queryForObject("SELECT lease_token FROM ai_run WHERE id=?",String.class,task.runId()));assertTrue(audit.record(task.runId(),report(task,known(1))).get("recorded"));assertEquals(7,count("SELECT total_tokens FROM ai_provider_request_usage WHERE run_id=?",task.runId()));assertEquals("canceled",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals("",db.queryForObject("SELECT output_text FROM ai_run WHERE id=?",String.class,task.runId()));assertNull(db.queryForObject("SELECT usage_json FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals(0,count("SELECT COUNT(*) FROM ai_model_usage WHERE run_id=?",task.runId()));assertEquals(events,count("SELECT last_event_seq FROM ai_conversation WHERE id=?",conversation));assertEquals(409,assertThrows(ConversationProblem.class,()->ai.complete(task.runId(),new Complete(task.leaseToken(),0L,"stop",null,null))).status());assertEquals(409,assertThrows(ConversationProblem.class,()->ai.fail(task.runId(),new Fail(task.leaseToken(),"PROVIDER_TIMEOUT"))).status());}
    @Test void overwrittenAttemptLeaseCannotAdoptNewAttemptButOldCostKeepsOriginalModel()throws Exception {connect(false);Task first=claim();db.update("UPDATE ai_run SET lease_expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE id=?",first.runId());ai.setModel("qwen-plus");Task second=claim();assertEquals(2,second.attempt());assertNotEquals(first.leaseToken(),second.leaseToken());audit.record(first.runId(),report(first,known(1)));audit.record(second.runId(),report(second,new ProviderRequest(1,null,null,null)));assertEquals("qwen-flash",db.queryForObject("SELECT model FROM ai_provider_request_usage WHERE run_id=? AND attempt=1",String.class,first.runId()));assertEquals("qwen-plus",db.queryForObject("SELECT model FROM ai_provider_request_usage WHERE run_id=? AND attempt=2",String.class,first.runId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=? AND attempt=2 AND total_tokens IS NULL",first.runId()));assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(first.runId(),new UsageAudit(first.leaseToken(),2,List.of(known(1))))).status());assertEquals(second.leaseToken(),db.queryForObject("SELECT lease_token FROM ai_run WHERE id=?",String.class,second.runId()));assertEquals("running",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,second.runId()));}
    @Test void finalizedPrefixReplayAndConcurrentDuplicatesAreIdempotentAndConflictsNeverOverwrite()throws Exception {connect(false);Task task=claim();var body=report(task,known(1));try(var pool=Executors.newFixedThreadPool(4)){CountDownLatch start=new CountDownLatch(1);List<Future<?>> pending=new ArrayList<>();for(int i=0;i<8;i++)pending.add(pool.submit(()->{start.await();return audit.record(task.runId(),body);}));start.countDown();for(var result:pending)result.get(5,TimeUnit.SECONDS);}assertEquals(1,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=?",task.runId()));audit.record(task.runId(),report(task,known(1),new ProviderRequest(2,null,null,null)));audit.record(task.runId(),body);assertEquals(2,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=?",task.runId()));assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),report(task,new ProviderRequest(1,null,null,"tool_calls")))).status());assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),report(task,new ProviderRequest(1,"changed",new Usage(5L,2L,7L),"tool_calls")))).status());assertEquals(7,count("SELECT total_tokens FROM ai_provider_request_usage WHERE run_id=? AND round_number=1",task.runId()));assertEquals(400,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),report(task,known(1),known(3)))).status());}
    @Test void earlyPerRoundAuditAndNormalCompletionShareOneImmutableLedger()throws Exception {connect(false);Task task=claim();audit.record(task.runId(),report(task,known(1)));List<ProviderRequest> requests=List.of(known(1),known(2));ai.complete(task.runId(),new Complete(task.leaseToken(),0L,"stop",new Usage(10L,4L,14L),null,requests,1));assertEquals(2,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=?",task.runId()));assertEquals(14,count("SELECT total_tokens FROM ai_model_usage WHERE run_id=?",task.runId()));long events=count("SELECT last_event_seq FROM ai_conversation WHERE id=?",conversation);audit.record(task.runId(),report(task,known(1),known(2)));assertEquals(events,count("SELECT last_event_seq FROM ai_conversation WHERE id=?",conversation));assertEquals("completed",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));}
    @Test void terminalCallbackCannotOmitAnAlreadyAuditedRequestOrChangeItsFacts()throws Exception {connect(false);Task task=claim();audit.record(task.runId(),report(task,known(1),new ProviderRequest(2,null,null,null)));assertEquals(409,assertThrows(ConversationProblem.class,()->ai.complete(task.runId(),new Complete(task.leaseToken(),0L,"stop",new Usage(5L,2L,7L),null,List.of(known(1)),1))).status());assertEquals("running",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));ai.fail(task.runId(),new Fail(task.leaseToken(),"PROVIDER_TIMEOUT",null,List.of(known(1),new ProviderRequest(2,null,null,null)),1));assertEquals("failed",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals(0,count("SELECT COUNT(*) FROM ai_model_usage WHERE run_id=?",task.runId()));assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),report(task,known(1),known(2)))).status());}
    @Test void actualRevokedSourceDisabledAccountAndFeatureOffStillPermitAuditButNoContent()throws Exception {connect(true);Task task=claim();db.update("UPDATE external_access_token SET revoked_at=CURRENT_TIMESTAMP(3) WHERE id=?",principal.tokenId());assertThrows(ConversationProblem.class,()->ai.delta(task.runId(),new Delta(task.leaseToken(),1L,"must not publish")));ai.cancel(owner,conversation,task.runId());ai.setEnabled(false);db.update("UPDATE sys_user SET status=0 WHERE id=?",owner);assertTrue(audit.record(task.runId(),report(task,known(1))).get("recorded"));assertEquals(7,count("SELECT total_tokens FROM ai_provider_request_usage WHERE run_id=?",task.runId()));assertEquals("canceled",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals("",db.queryForObject("SELECT output_text FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),new UsageAudit("b".repeat(64),task.attempt(),List.of(known(1))))).status());}
    @Test void cancelAndAuditRaceCommitsBothFeeAndTerminalWithoutDeadlock()throws Exception {connect(false);Task task=claim();try(var pool=Executors.newFixedThreadPool(2)){CountDownLatch start=new CountDownLatch(1);var fee=pool.submit(()->{start.await();return audit.record(task.runId(),report(task,known(1)));});var cancel=pool.submit(()->{start.await();return ai.cancel(owner,conversation,task.runId());});start.countDown();fee.get(5,TimeUnit.SECONDS);cancel.get(5,TimeUnit.SECONDS);}assertEquals("canceled",db.queryForObject("SELECT status FROM ai_run WHERE id=?",String.class,task.runId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=?",task.runId()));assertEquals(7,count("SELECT total_tokens FROM ai_provider_request_usage WHERE run_id=?",task.runId()));}
    @Test void claimRollbackCannotLeaveAnUndeliveredDispatchCapability()throws Exception {connect(false);var skill=mock(AiSkillService.class);when(skill.applyContext(anyString(),anyList())).thenThrow(new IllegalStateException("Synthetic claim transaction failure"));ai.setSkills(skill);assertThrows(IllegalStateException.class,()->ai.claim(new Claim("failed-dispatch")));assertEquals(0,count("SELECT COUNT(*) FROM ai_provider_attempt_dispatch d JOIN ai_run r ON r.id=d.run_id WHERE r.conversation_id=?",conversation));assertEquals(0,count("SELECT attempt FROM ai_run WHERE conversation_id=?",conversation));assertEquals("queued",db.queryForObject("SELECT status FROM ai_run WHERE conversation_id=?",String.class,conversation));ai.setSkills(null);Task task=claim();assertEquals(1,task.attempt());assertEquals(1,count("SELECT COUNT(*) FROM ai_provider_attempt_dispatch WHERE run_id=?",task.runId()));}
    @Test void noCurrentLeaseFallbackCanInventAHistoricalDispatchForLegacyTask()throws Exception {connect(false);ai.setUsageAudit(null);Task task=claim();assertNull(task.usageAudit());assertFalse(json.valueToTree(task).has("usage_audit"));assertEquals(409,assertThrows(ConversationProblem.class,()->audit.record(task.runId(),report(task,known(1)))).status());assertEquals(0,count("SELECT COUNT(*) FROM ai_provider_request_usage WHERE run_id=?",task.runId()));}
}
